import{_ as t,o as a,c as r,a4 as e}from"./chunks/framework.9tZL7ZIQ.js";const u=JSON.parse('{"title":"财务准则","description":"","frontmatter":{},"headers":[],"relativePath":"09_books/巴菲特之道/准则/03_财务准则.md","filePath":"09_books/巴菲特之道/准则/03_财务准则.md"}'),l={name:"09_books/巴菲特之道/准则/03_财务准则.md"};function n(i,o,s,h,p,c){return a(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="财务准则" tabindex="-1">财务准则 <a class="header-anchor" href="#财务准则" aria-label="Permalink to &quot;财务准则&quot;">​</a></h1><p>财务数据是巴菲特量化分析企业的核心工具。他通过财务指标筛选出优秀的投资标的。</p><h2 id="三大财务准则" tabindex="-1">三大财务准则 <a class="header-anchor" href="#三大财务准则" aria-label="Permalink to &quot;三大财务准则&quot;">​</a></h2><h3 id="_1-净资产收益率-roe" tabindex="-1">1. 净资产收益率 (ROE) <a class="header-anchor" href="#_1-净资产收益率-roe" aria-label="Permalink to &quot;1. 净资产收益率 (ROE)&quot;">​</a></h3><blockquote><p><strong>&quot;净资产收益率是衡量企业盈利能力的关键指标。&quot;</strong></p></blockquote><p>巴菲特偏好那些能够持续产生高净资产收益率的公司。</p><p><strong>核心要点：</strong></p><ul><li>净资产收益率 ≥ 15%</li><li>长期稳定而非一次性高企</li><li>排除高杠杆因素</li></ul><p><strong>计算公式：</strong> 净利润 ÷ 股东权益</p><hr><h3 id="_2-股东回报率" tabindex="-1">2. 股东回报率 <a class="header-anchor" href="#_2-股东回报率" aria-label="Permalink to &quot;2. 股东回报率&quot;">​</a></h3><blockquote><p><strong>&quot;最重要的指标是每股内在价值的增长。&quot;</strong></p></blockquote><p>巴菲特关注公司如何利用留存收益为股东创造价值。</p><p><strong>核心要点：</strong></p><ul><li>留存收益的再投资回报</li><li>股票回购提升每股价值</li><li>分红（但巴菲特偏好不分红）</li></ul><p><strong>相关阅读：</strong> <a href="/02_concepts/compounding.html">复利</a></p><hr><h3 id="_3-利润率" tabindex="-1">3. 利润率 <a class="header-anchor" href="#_3-利润率" aria-label="Permalink to &quot;3. 利润率&quot;">​</a></h3><blockquote><p><strong>&quot;定价权是检验企业护城河的试金石。&quot;</strong></p></blockquote><p>高利润率往往意味着公司拥有强大的竞争优势和定价权。</p><p><strong>核心要点：</strong></p><ul><li>毛利率 ≥ 40%</li><li>营业利润率稳定</li><li>费用控制得当</li></ul><p><strong>相关阅读：</strong> <a href="/02_concepts/safety-margin.html">安全边际</a></p><hr><h2 id="财务分析的三个关键问题" tabindex="-1">财务分析的三个关键问题 <a class="header-anchor" href="#财务分析的三个关键问题" aria-label="Permalink to &quot;财务分析的三个关键问题&quot;">​</a></h2><p>巴菲特在分析财务报表时会问：</p><ol><li><strong>这家公司大约值多少钱？</strong> → <a href="/02_concepts/intrinsic-value.html">内在价值</a></li><li><strong>公司能否保持这个价值？</strong> → <a href="/02_concepts/moat.html">护城河</a></li><li><strong>管理层能否把事情做好？</strong> → <a href="/search.html?q=管理准则">管理准则</a></li></ol><hr><h2 id="案例-苹果" tabindex="-1">案例：苹果 <a class="header-anchor" href="#案例-苹果" aria-label="Permalink to &quot;案例：苹果&quot;">​</a></h2><p>巴菲特2016年重仓苹果，正是基于这三个财务准则：</p><ul><li><strong>ROE</strong>：苹果的净资产收益率远超20%</li><li><strong>股东回报</strong>：大规模股票回购</li><li><strong>利润率</strong>：极高的毛利率和净利润率</li></ul><p><strong>相关阅读：</strong> <a href="/03_companies/苹果公司.html">苹果</a></p>',32)])])}const g=t(l,[["render",n]]);export{u as __pageData,g as default};
